def comps(S):
    S=set(S); seen=set(); out=[]
    for c in S:
        if c in seen: continue
        stack=[c]; seen.add(c); comp=[]
        while stack:
            x=stack.pop(); comp.append(x)
            r,cc=x
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    n=(r+dr,cc+dc)
                    if n in S and n not in seen:
                        seen.add(n); stack.append(n)
        out.append(comp)
    return out
