def connected_subsets(S, sizes=(4,12), maxn=200000):
    S=set(S); out=set()
    from collections import deque
    seen=0
    def norm(sub):
        r0=min(r for r,c in sub); c0=min(c for r,c in sub)
        return tuple(sorted((r-r0,c-c0) for r,c in sub))
    starts=sorted(S)
    results={}
    for s in starts:
        frontier=[{s}]
        for _ in range(max(sizes)):
            nxt=[]
            for sub in frontier:
                key=norm(sub)
                if key not in results:
                    results[key]=sub
                if len(sub)>=max(sizes): continue
                nb={(r+dr,c+dc) for r,c in sub for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))} & S - sub
                for cell in nb:
                    nxt.append(sub|{cell})
            frontier=nxt
            if len(frontier)>maxn: break
    return results
