    pred=set()
    for r in range(R):
        for c in range(C):
            cells=[(r+a,c+b) for a,b in T]
            if not all(0<=rr<R and 0<=cc<C for rr,cc in cells): continue
            inside=[cell for cell in cells if cell in sup]
            if inside and set(cells)>=set(inside)==set(cells)&set(cells):
                # all support cells inside footprint are template cells, and at least... ?
                pred|=set(inside)
    return pred
